// Edit these values once. Pricing is per 1M tokens for the model below.
return {
  json: {
    ...$json,
    _cfg: {
      agency_name: 'Your Agency',
      sheet_id: 'PASTE_AGENCY_DB_SHEET_ID',
      skills_base_url: 'https://raw.githubusercontent.com/coreyhaines31/marketingskills/main',
      model: 'claude-opus-5-5',
      price_in: 4, price_out: 20, price_cache_read: 0.2, price_cache_write: 5,
    },
  },
};

const inp = $('Brain Config').item.json;
const b = inp.brain || {};
const cfg = inp._cfg;
let playbook = typeof $json.playbook === 'string' ? $json.playbook : '';
if (!playbook.includes('\n') || /^\s*(404|Not Found)/i.test(playbook)) playbook = '';
playbook = playbook.replace(/^---[\s\S]*?\n---\s*/, '');

const operating = `You are a senior strategist at ${cfg.agency_name}, a marketing agency. You are running inside an automated n8n pipeline:
- Nobody can answer follow-up questions. Where the playbook says to ask the user something or to read a context file, use the client context supplied in the message instead, make the most reasonable assumption, and state it briefly.
- Ground every claim in the supplied context. Never invent metrics, quotes, prices, or results; if data is missing, say what is missing.
- Write for a busy agency team and their clients: specific, concrete, and actionable. No filler.
- Return only what the task asks for.`;

const system = [{
  type: 'text',
  text: playbook
    ? `${operating}\n\nApply this playbook as your working method:\n<playbook skill="${b.skill}">\n${playbook}\n</playbook>`
    : operating,
  cache_control: { type: 'ephemeral' },
}];

const ctx = typeof b.context === 'string' ? b.context : JSON.stringify(b.context ?? {}, null, 2);
const body = {
  model: cfg.model,
  max_tokens: b.max_tokens || 16000,
  system,
  messages: [{ role: 'user', content: `<context>\n${ctx}\n</context>\n\n${b.task || 'Summarize the context.'}` }],
  thinking: { type: 'adaptive' },
  output_config: { effort: b.effort || 'medium' },
  fallbacks: 'default',
};
if (b.schema) body.output_config.format = { type: 'json_schema', schema: b.schema };
return { json: { body } };

const inp = $('Brain Config').item.json;
const b = inp.brain || {};
const cfg = inp._cfg;
const res = $json;
let ai = null, ai_text = '', ai_error = null;

if (res.error) {
  ai_error = typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error));
} else if (res.stop_reason === 'refusal') {
  ai_error = `refusal (${res.stop_details?.category || 'unspecified'})`;
} else {
  ai_text = (res.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('\n').trim();
  if (res.stop_reason === 'max_tokens') ai_error = 'truncated: raise brain.max_tokens';
  if (b.schema) {
    try { ai = JSON.parse(ai_text); } catch (e) { ai_error = ai_error || `invalid JSON: ${e.message}`; }
  } else {
    ai = ai_text;
  }
}

const u = res.usage || {};
const cost = ((u.input_tokens || 0) * cfg.price_in + (u.output_tokens || 0) * cfg.price_out
  + (u.cache_read_input_tokens || 0) * cfg.price_cache_read
  + (u.cache_creation_input_tokens || 0) * cfg.price_cache_write) / 1e6;

const { brain, _cfg, ...rest } = inp;
return {
  json: {
    ...rest,
    ai, ai_text, ai_error,
    ai_meta: {
      skill: b.skill, caller: b.caller || '', client: b.client || '', model: res.model || cfg.model,
      stop_reason: res.stop_reason || 'error', input_tokens: u.input_tokens || 0,
      output_tokens: u.output_tokens || 0, cache_read_tokens: u.cache_read_input_tokens || 0,
      cache_write_tokens: u.cache_creation_input_tokens || 0, cost_usd: Number(cost.toFixed(5)),
    },
  },
};

const m = $json.ai_meta;
return { json: {
  timestamp: new Date().toISOString(), caller: m.caller, client: m.client, skill: m.skill, model: m.model,
  input_tokens: m.input_tokens, output_tokens: m.output_tokens, cache_read_tokens: m.cache_read_tokens,
  cache_write_tokens: m.cache_write_tokens, est_cost_usd: m.cost_usd, stop_reason: m.stop_reason,
  error: $json.ai_error || '',
} };
